	if err != nil {
		return nil, err
	}

	accessible, filtered := authz.NamespacesFromContext(ctx)
	if filtered {
		allowed := make(map[string]struct{}, len(accessible))
		for _, namespace := range accessible {
			allowed[namespace] = struct{}{}
		}
		filteredResults := make([]*flipt.Namespace, 0, len(results.Results))
		for _, namespace := range results.Results {
			if _, ok := allowed[namespace.Key]; ok {
				filteredResults = append(filteredResults, namespace)
			}
		}
		results.Results = filteredResults
	}

	resp := flipt.NamespaceList{
		Namespaces: results.Results,
	}

	var total uint64
	if filtered {
		total = uint64(len(results.Results))
	} else {
		total, err = s.store.CountNamespaces(ctx, ref)
		if err != nil {
			return nil, err
		}
	}

	resp.TotalCount = int32(total)
	resp.NextPageToken = results.NextPageToken

	s.logger.Debug("list namespaces", zap.Stringer("response", &resp))
	return &resp, nil
}

